// Local offline listening stimuli. Float PCM preserves every sample generated by
// the bound processor, including a diagnostic plan that failed a selected limit.
void writeListeningWave(const juce::File& path,const juce::File& source,const ServiceContext& context,const measurement::Result& expected)
{
    expect(!path.exists()&&context.sourceFilesMatch(),"new listening copy and matching original media");
    juce::AudioFormatManager formats;formats.registerBasicFormats();
    std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(source));
    const int channels=context.fileLayout.count,rate=int(context.media.sampleRate);
    const auto frames=context.media.frames;const auto bytes=frames*channels*4;
    expect(reader&&int(reader->numChannels)==channels&&reader->lengthInSamples==frames&&bytes<INT32_MAX,"bounded source frames and ordered channels");
    auto out=path.createOutputStream();expect(bool(out),"open new local listening wave");
    out->write("RIFF",4);out->writeInt(36+int(bytes));out->write("WAVEfmt ",8);out->writeInt(16);out->writeShort(3);out->writeShort(short(channels));
    out->writeInt(rate);out->writeInt(rate*channels*4);out->writeShort(short(channels*4));out->writeShort(32);out->write("data",4);out->writeInt(int(bytes));
    ProgrammeGainProcessor processor(context.processing);
    juce::AudioBuffer<float> audio(channels,4096);std::vector<float> interleaved(4096*channels);
    for(int64_t first=0;first<frames;first+=4096)
    {
        const int n=int(std::min<int64_t>(4096,frames-first));
        if(!reader->read(audio.getArrayOfWritePointers(),channels,first,n)||!processor.process(audio.getArrayOfWritePointers(),channels,n,first))
            throw std::runtime_error("Listening decode or processing failed");
        for(int i=0;i<n;++i)for(int ch=0;ch<channels;++ch)interleaved[i*channels+ch]=audio.getSample(ch,i);
        if(!out->write(interleaved.data(),size_t(n*channels)*sizeof(float)))throw std::runtime_error("Listening wave write failed");
    }
    out->flush();expect(out->getStatus().wasOk(),"complete source-aligned float PCM");out.reset();
    reader.reset(formats.createReaderFor(path));
    expect(reader&&reader->usesFloatingPointData&&reader->lengthInSamples==frames,"reopen finalized float PCM");
    measurement::OfflineMeasurement meter(rate,OfflineAnalysisService::measurementRoles(context.fileLayout));
    for(int64_t first=0;first<frames;first+=4096)
    {
        const int n=int(std::min<int64_t>(4096,frames-first));
        if(!reader->read(audio.getArrayOfWritePointers(),channels,first,n))throw std::runtime_error("Failed listening wave readback");
        meter.push(audio.getArrayOfReadPointers(),n);
    }
    const auto& m=meter.finish();
    expect(m.integrated.value==expected.integrated.value&&m.lra.value==expected.lra.value&&m.p10==expected.p10&&m.p95==expected.p95
        &&m.channelTruePeaks==expected.channelTruePeaks&&m.truePeakEighthFrames==expected.truePeakEighthFrames&&m.samplePeakFrames==expected.samplePeakFrames
        &&m.momentaryMax.value==expected.momentaryMax.value&&m.shortTermMax.value==expected.shortTermMax.value,"reopened listening PCM exactly matches full-plan loudness, gates' percentiles, channel true peaks and locations");
}
void savedListening(const juce::File& root,const juce::File& file)
{
    expect(root.createDirectory().wasOk(),"new preserved-session comparison directory");JobControl job;
    auto saved=sf::read(file,job);expect(bool(saved.document),"read preserved session");
    auto verified=sf::verify(*saved.document,job);expect(bool(verified.prepared),"verify original media and saved plan");
    auto model=verified.prepared->model;const auto fresh=measuredComposition(model,MeasurementDomain::currentState);
    writeListeningWave(root.getChildFile("programme.wav"),model.sourceDocument.file,model.measurementContext(MeasurementDomain::currentState),fresh.detail);
}
